query WorkshopProject($slug: String!) {
  workshopProjects(slugs: [$slug], first: 1) {
    nodes {
      id
      slug
      name
      revision
      phase
      kind
      brief
      requirements
      measurementNotes
      circuitNotes
      updatedAt
      productRevision {
        id
        title
        url
      }
      builds {
        id
        status
        current
        stale
        repository
        sourceDir
        sourceCommit
        runner
        compiler
        createdAt
        finishedAt
        error
        tests {
          name
          status
          detail
        }
        artifacts {
          path
          bytes
          contentType
        }
      }
      evidence {
        stage
        outcome
        note
        operator
        at
      }
      research {
        name
        kind
        url
        notes
        decision
      }
      concepts {
        caption
        model
        createdAt
      }
    }
  }
}

query WorkshopProjectHandoff($input: WorkshopProjectHandoffInput!) {
  workshopProjectHandoff(input: $input)
}

query WorkshopProjects($first: Int = 100, $after: String, $search: String, $filter: WorkshopProjectFilter, $orderBy: WorkshopProjectOrder) {
  workshopProjects(
    first: $first
    after: $after
    search: $search
    filter: $filter
    orderBy: $orderBy
  ) {
    nodes {
      id
      slug
      name
      revision
      phase
      kind
      brief
      productRevisionId
      productRevisionTitle
      updatedAt
    }
    pageInfo {
      endCursor
      hasNextPage
    }
  }
}

query WorkshopUnits($first: Int = 100, $after: String, $search: String, $filter: WorkshopUnitFilter) {
  workshopUnits(first: $first, after: $after, search: $search, filter: $filter) {
    nodes {
      id
      partNumber
      mpn
      mac
      serial
      status
      location
      projectId
      firmware
      notes
      updatedAt
    }
    pageInfo {
      endCursor
      hasNextPage
    }
  }
}
